-- =============================================================================
-- Career vacancies — official company data (List Vacancy Technical per Sept 2026)
-- Source: Career_Eng.docx provided by the client. 13 positions.
-- This migration REPLACES the career listing: it removes any position NOT in
-- this document, then upserts the 13 official roles (keyed on slug, so re-running
-- is safe and keeps existing IDs / job_applications links intact).
-- Location set to Jakarta for all; departments grouped into the 'role' filter.
-- Run in phpMyAdmin on the live database.
-- =============================================================================

START TRANSACTION;

-- 1) Remove every vacancy that is not in the official document.
DELETE FROM `career` WHERE `slug` NOT IN ('account-manager', 'product-manager', 'solution-architect', 'cybersecurity-consultant', 'network-engineer', 'server-storage-engineer', 'technical-support-server-storage', 'backup-support-engineer', 'cybersecurity-engineer', 'project-manager', 'it-project-admin', 'technical-writer', 'ai-engineer');

-- 2) Upsert the 13 official vacancies (in document order).
INSERT INTO `career`
  (`judul`,`slug`,`role`,`lokasi`,`tipe`,`jenjang`,`pengalaman`,`deskripsi`,`responsibilities`,`requirements`,`deadline`,`urutan`,`is_active`)
VALUES
  ('Account Manager', 'account-manager', 'Sales & Business', 'Jakarta', 'Full-time', 'Diploma / Bachelor', 'Experienced', 'Grow and manage enterprise accounts — drive business development and close complex IT solution deals.', '<ul><li>Aggressively develop and manage accounts.</li><li>Analyze, Negotiate and Close complex deals for IT Solution.</li><li>Setting appointments and presentation with viable prospects.</li><li>Build strong and long-term relationship with clients, partners and principals.</li><li>Employ a consultative selling approach to ensure success in achieving the Sales Quota.</li><li>Closely cooperating with other departments involved with your accounts.</li></ul>', '<ul><li>Maximum 32 years old.</li><li>Diploma or Bachelor degree from any major.</li><li>High Passionate for sales activity or business development.</li><li>Having good networking, especially in management level.</li><li>Having experience in creating/prospecting and managing accounts.</li><li>Good in written &amp; verbal English communication.</li><li>Good negotiation &amp; presentation.</li><li>Highly motivated, able to work with target and fast learner.</li><li>Detail oriented, strong analytical &amp; planning.</li></ul>', NULL, 1, 1),
  ('Product Manager', 'product-manager', 'Sales & Business', 'Jakarta', 'Full-time', 'Bachelor', 'Min. 2 years', 'Own product strategy and roadmap — translate market and customer needs into winning IT solutions.', '<ul><li>Define product strategy, positioning, and roadmap aligned with business and market needs.</li><li>Conduct customer and market research to identify opportunities, pain points, and competitive insights.</li><li>Translate customer needs into clear product requirements, solution concepts, and value propositions.</li><li>Collaborate with Sales, Technical, and Business teams to drive product development and go-to-market initiatives.</li><li>Monitor product performance, market trends, and customer feedback to identify improvements and growth opportunities.</li></ul>', '<ul><li>Bachelor’s degree in Information Technology, Computer Science, Business, Marketing, or related fields.</li><li>Minimum 2 years of experience in Product Management, Solution Sales, Business Development, or related roles.</li><li>Strong understanding of product strategy, market analysis, customer needs, and business value.</li><li>Able to understand high-level technical concepts, including solution architecture, topology, data flow, and BOQ.</li><li>Strong communication, stakeholder management, analytical thinking, storytelling, and problem-solving skills.</li></ul>', NULL, 2, 1),
  ('Solution Architect', 'solution-architect', 'IT Infrastructure', 'Jakarta', 'Full-time', 'Bachelor', '1–3 years', 'Design tailored, right-sized IT infrastructure solutions and partner with Sales as the technical advisor.', '<ul><li>Partner closely with the Sales team as a technical advisor to support solution-based selling and drive the pre-sales process.</li><li>Conduct on-site assessments to gather requirements and design tailored, right-sized IT infrastructure solutions.</li><li>Deliver in-depth technical presentations and lead Proof of Concept (POC) trials to validate solution effectiveness for clients.</li><li>Manage technical documentation, including preparing compelling proposals and participating in tender meetings (aanwijzing).</li><li>Maintain a focus on client expectations while continuously evaluating industry trends and new technologies to provide best-in-class solutions.</li></ul>', '<ul><li>Bachelor’s Degree in Computer Science, Information Technology, or related field.</li><li>Have 1-3 years of experience in IT infrastructure, presales, or technical roles.</li><li>Solid understanding of servers &amp; storage solutions, networking technologies, and backup and disaster recovery.</li><li>(Preferred) Experience with leading IT vendors such as Dell, HPE, Cisco, Veeam, or VMware.</li><li>Proficient in English (both active and passive).</li></ul>', NULL, 3, 1),
  ('Cybersecurity Consultant', 'cybersecurity-consultant', 'Cybersecurity', 'Jakarta', 'Full-time', 'Bachelor', '3–5 years', 'Support cybersecurity solution-based selling — lead POCs and provide security expertise through the sales cycle.', '<ul><li>Collaborate closely with the Sales and Solution Architect teams to support cybersecurity solution-based selling.</li><li>Lead Cybersecurity Proof of Concept (POC) processes to validate solutions.</li><li>Provide cybersecurity technical expertise during tender, aanwijzing, and clarification stages.</li><li>Customer-centric professional who ensures cybersecurity solutions meet client expectations while continuously staying updated on industry trends.</li></ul>', '<ul><li>Bachelor’s Degree in Computer Science, Information Technology, or related field.</li><li>Have 3–5 years of hands-on experience in a relevant role.</li><li>Solid understanding of network security (firewall, IPS/IDS, VPN), threat intelligence, SOC, SIEM, and other security solutions.</li><li>(Preferred) Experience with leading IT vendors such as Cisco, Fortinet, Palo Alto, F5, Elastic, Cyble, or etc.</li><li>(Preferred) Having cybersecurity related certification such as CEH, CompTIA Security+, CISSP, CCNP Security, NSE, or vendor-specific cybersecurity certifications.</li></ul>', NULL, 4, 1),
  ('Network Engineer', 'network-engineer', 'IT Infrastructure', 'Jakarta', 'Full-time', 'Bachelor', 'Min. 2 years', 'Deploy, secure, and keep enterprise networks running smoothly and reliably.', '<ul><li>Deploy and monitor network performance to ensure stable, reliable, and smooth operations.</li><li>Diagnose and resolve hardware, software, and complex network system issues efficiently.</li><li>Manage system updates, including patches, hotfixes, and security configurations to maintain infrastructure integrity.</li><li>Maintain precise records of all network configurations, system changes, and updates.</li><li>Generate regular reports on network health, security incidents, and key performance metrics.</li><li>Partner with IT teams and provide end-user assistance for all network-related concerns.</li></ul>', '<ul><li>Bachelor’s Degree in Information Technology, Computer Science, or related IT field.</li><li>Minimum 2 years of experience in networking, network security, or similar technical roles.</li><li>Certifications: CCNA/CCNP and Fortinet NSE 4 / FCP (or equivalent network security certification).</li><li>Strong understanding of networking and security protocols and standards (e.g., TCP/IP, DNS, DHCP, OSPF, EIGRP, BGP), plus security principles and practices (firewalls, access control, VPN, intrusion detection/prevention).</li><li>Hands-on experience with networking and security hardware/software: routers, switches, firewalls, monitoring and security tools.</li><li>Knowledge or implementation experience in SDN (Software Defined Networking) is a plus.</li></ul>', NULL, 5, 1),
  ('Server Storage Engineer', 'server-storage-engineer', 'IT Infrastructure', 'Jakarta', 'Full-time', 'Bachelor', '3–5 years', 'Build and operate enterprise server, storage, virtualization, and HCI infrastructure.', '<ul><li>Implement scalable Server and Storage (HCI) solutions.</li><li>Support daily operations of server, storage, and virtualization infrastructure.</li><li>Partner with application, database, and network teams to integrate and support technical needs.</li><li>Assist routine maintenance activities such as patching, firmware updates, and system checks.</li><li>Maintain comprehensive records of system configurations, operational procedures, and troubleshooting protocols.</li></ul>', '<ul><li>Bachelor’s Degree in Information Technology, Computer Science, or a related field.</li><li>Minimum 3–5 years of experience in Server, Storage, Virtualization, or HCI engineering within an enterprise environment.</li><li>Strong hands-on experience with enterprise server and storage infrastructure, including installation, configuration, troubleshooting, maintenance, and lifecycle management.</li><li>Solid experience with virtualization platforms and HCI environments, including VM, host, cluster, datastore, resource management, and performance troubleshooting.</li><li>Familiar with enterprise infrastructure vendors and technologies such as Dell, HPE, VMware, Nutanix, or equivalent platforms.</li><li>Strong understanding of storage concepts, including SAN/NAS, RAID, IOPS, throughput, capacity planning, storage connectivity, and data protection.</li><li>Good understanding of infrastructure networking fundamentals, including TCP/IP, VLAN, trunking, LACP, routing, and connectivity troubleshooting.</li><li>Experienced in infrastructure monitoring, performance analysis, incident management, RCA, change management, and SLA-driven operations.</li></ul>', NULL, 6, 1),
  ('Technical Support - Server Storage', 'technical-support-server-storage', 'IT Infrastructure', 'Jakarta', 'Full-time', 'Bachelor', 'Fresh Graduate', 'Entry-level role supporting server, storage, and network infrastructure — fresh graduates welcome.', '<ul><li>Assist in the installation, configuration, and troubleshooting of LAN/WAN networks.</li><li>Support maintenance of network devices (routers, switches, firewalls, wireless access points).</li><li>Support configuration and basic maintenance of SAN/NAS storage systems.</li><li>Assist in implementing basic security measures and monitoring infrastructure health.</li><li>Provide first-level technical support to end-users for hardware and software issues.</li><li>Maintain clear and organized technical documentation.</li></ul>', '<ul><li>Bachelor’s Degree in Information Technology, Computer Science, or related IT field.</li><li>Fresh graduates are welcome to apply.</li><li>Strong interest in IT infrastructure, server, and storage technologies.</li><li>Basic knowledge of networking, servers, virtualization, and cloud fundamentals.</li></ul>', NULL, 7, 1),
  ('Backup Support Engineer', 'backup-support-engineer', 'IT Infrastructure', 'Jakarta', 'Full-time', 'Bachelor', 'Min. 2 years', 'Run enterprise backup and restore operations — ensure data protection, recovery, and SLA targets.', '<ul><li>Execute and monitor daily backup/restore operations, ensuring data retention and repository capacity align with established SOPs and SLAs.</li><li>Resolve backup failures and performance bottlenecks, conducting Root Cause Analysis (RCA) to implement effective preventive actions.</li><li>Manage complex restore requests for files, VMs, and diverse databases (SQL, NoSQL) while ensuring data consistency and recovery point integrity.</li><li>Perform system tuning and coordinate with cross-functional teams (Storage, Network, Virtualization) to maintain optimal backup pathways and performance.</li></ul>', '<ul><li>Bachelor’s Degree in Information Technology, Computer Science, or related IT field.</li><li>Minimum 2 years of experience in enterprise backup operations/support (L2 level).</li><li>Hands-on experience with at least one enterprise backup platform in production environments.</li><li>Experience handling backup and restore for databases and virtualized infrastructures.</li><li>Strong understanding of storage concepts (IOPS, throughput, retention), networking fundamentals (latency, bandwidth), and virtualization environments.</li><li>Comfortable working in Linux environments, analyzing logs, performing basic scripting for automation, working with ticketing systems, and meeting SLA targets with clear communication and structured troubleshooting approach.</li></ul>', NULL, 8, 1),
  ('Cybersecurity Engineer', 'cybersecurity-engineer', 'Cybersecurity', 'Jakarta', 'Full-time', 'Bachelor', 'Fresh Graduate', 'Entry-level security role — monitor, scan, and harden systems. Fresh graduates welcome.', '<ul><li>Assist in the deployment and initial configuration of security tools.</li><li>Monitor SIEM dashboards to identify security events, perform initial log analysis, and escalate potential incidents to senior analysts for remediation.</li><li>Conduct regular vulnerability scans, analyze results to identify system weaknesses, and coordinate with IT teams to ensure timely patching and hardening.</li><li>Implement security baselines on servers and workstations to minimize the attack surface, ensuring alignment with internal policies and industry standards.</li><li>Prepare technical reports on security health metrics and maintain up-to-date documentation for incident response playbooks and system configurations.</li></ul>', '<ul><li>Bachelor’s Degree in Information Technology, Computer Science, or related IT field.</li><li>Fresh graduates are welcome to apply.</li><li>Strong understanding of TCP/IP, Firewalls, and common cyber threats.</li><li>Familiarity with Windows and Linux operating systems, including basic command-line usage.</li><li>Exposure to security tools like Antivirus, Wireshark, or basic Vulnerability Scanners from college projects or labs.</li><li>Strong interest in Cybersecurity technologies.</li></ul>', NULL, 9, 1),
  ('Project Manager', 'project-manager', 'Project Management', 'Jakarta', 'Full-time', 'Bachelor', 'Experienced', 'Lead IT project delivery — coordinate teams, documentation, schedules, and stakeholder satisfaction.', '<ul><li>Preparing project documentation (timeline, Pre-CoM/CoM slides, reports).</li><li>Coordinating with internal teams and customers.</li><li>Delegating tasks and monitoring progress.</li><li>Managing maintenance schedules and renewal tracking.</li><li>Handling emerging issues and ensuring stakeholder satisfaction.</li><li>Maintaining organized documentation and Google Drive records.</li></ul>', '<ul><li>Bachelor’s degree in IT, Computer Science, Industrial Engineering, or related field.</li><li>Experience in preparing project documentation.</li><li>Skilled in maintenance project management.</li><li>Proficient in Google Workspace and project management tools.</li><li>Familiar with IT infrastructure or solution delivery processes.</li></ul>', NULL, 10, 1),
  ('IT Project Admin', 'it-project-admin', 'Project Management', 'Jakarta', 'Full-time', 'Bachelor', 'Fresh Graduate welcome', 'Keep IT projects on track — time tracking, reporting, and documentation support for PMs.', '<ul><li>Monitor and remind team members on daily and weekly time tracking (clocking).</li><li>Prepare time tracking and claim summaries.</li><li>Coordinate reminders for weekly project reports to customers.</li><li>Support internal weekly project meetings with PMs.</li><li>Maintain and organize project documentation and reports.</li><li>Track project administrative milestones such as BAST closure and maintenance expiry.</li></ul>', '<ul><li>Bachelor’s degree in Information Technology, Management, or any related field.</li><li>Preferably 1 year of experience as a Project Administrator in the IT industry (fresh graduates are welcome to apply).</li><li>Good communication skills in English (written and verbal).</li><li>Proficient in Microsoft Office (Word, Excel, PowerPoint).</li></ul>', NULL, 11, 1),
  ('Technical Writer', 'technical-writer', 'Documentation', 'Jakarta', 'Full-time', 'Bachelor (min GPA 3.25)', 'Fresh Graduate welcome', 'Produce clear, structured technical documentation — proposals, narratives, and system topologies.', '<ul><li>Communicate with division manager and technical teams in the preparation of technical documents.</li><li>Draft, edit, revise, and review technical documentation.</li><li>Develop narratives, including background information, executive summaries, and other required documentation content.</li><li>Create network and system topologies to support technical documentation needs.</li><li>Ensure documentation quality, consistency, and compliance with organizational standards.</li></ul>', '<ul><li>Bachelor’s degree in a relevant field with a minimum GPA of 3.25.</li><li>Preferably 1–2 years of experience in technical documentation or related roles (fresh graduates are welcome to apply).</li><li>Strong ability to understand technical and business requirements and translate them into clear, structured documentation.</li><li>Excellent writing skills with the ability to develop coherent narratives for documentation and compliance purposes.</li><li>Proficient in Microsoft Office, Google Workspace, and other office productivity tools.</li><li>Basic knowledge of IT Infrastructure is an advantage.</li></ul>', NULL, 12, 1),
  ('AI Engineer', 'ai-engineer', 'AI & Data', 'Jakarta', 'Full-time', 'Bachelor', 'Fresh Graduate', 'Build AI-driven features and data pipelines — LLM/RAG, ML, and ETL. Fresh graduates welcome.', '<ul><li>Support the development and integration of AI-driven features (e.g., chatbot, recommendation systems, automation tools).</li><li>Assist in implementing LLM-based approaches such as RAG and prompt optimization.</li><li>Perform data cleaning, exploration, and preprocessing to support model development.</li><li>Design and maintain simple data pipelines (ETL/ELT) to prepare data for AI models and analytics.</li><li>Assist in organizing and structuring data for data warehouse or data lake usage.</li><li>Ensure data quality, consistency, and basic validation across datasets.</li><li>Collaborate with the engineering team to deploy models into production environments.</li><li>Continuously stay updated with emerging AI technologies and industry trends.</li></ul>', '<ul><li>Fresh graduate with a Bachelor’s degree in Computer Science, Information Technology, or a related field.</li><li>Solid foundation in Python programming.</li><li>Basic understanding of machine learning concepts and workflows.</li><li>Basic understanding of data engineering concepts (ETL/ELT, data pipeline).</li><li>Strong SQL skills (Joins, Aggregation, Basic Optimization).</li><li>Familiar with Git/Version control is a plus.</li><li>Eager to learn and interested in AI development.</li></ul>', NULL, 13, 1)
ON DUPLICATE KEY UPDATE
  `judul`=VALUES(`judul`), `role`=VALUES(`role`), `lokasi`=VALUES(`lokasi`), `tipe`=VALUES(`tipe`),
  `jenjang`=VALUES(`jenjang`), `pengalaman`=VALUES(`pengalaman`), `deskripsi`=VALUES(`deskripsi`),
  `responsibilities`=VALUES(`responsibilities`), `requirements`=VALUES(`requirements`),
  `deadline`=VALUES(`deadline`), `urutan`=VALUES(`urutan`), `is_active`=1;

COMMIT;
